package io.xeros.content.combat.range;
import io.xeros.*;import io.xeros.model.*;import io.xeros.model.entity.*;import io.xeros.model.entity.player.*;import io.xeros.content.combat.weapon.*;
/** One roll owns both inventory consumption and any ground drop, preventing recovered-arrow duplication. */
public final class SoloAmmunition {
 private SoloAmmunition(){}
 public static int recovery(Player p){String body=io.xeros.model.definitions.ItemDef.forId(p.playerEquipment[4]).getName().toLowerCase();if(body.contains("platebody")||body.contains("chainbody"))return 0;int cape=p.playerEquipment[1];if(p.getCombatItems().usingAssembler())return 80;if(p.getCombatItems().usingAccumulator())return 72;if(cape==10498)return 60;return 0;}
 public static void consume(Player p,int slot){int id=p.playerEquipment[slot],count=p.playerEquipmentN[slot];if(id<0||count<=0)return;boolean disposable=id==10033||id==10034||id==11959||id==4740||id>=10142&&id<=10145;int roll=java.util.concurrent.ThreadLocalRandom.current().nextInt(100);if(!disposable&&roll<recovery(p))return;if(!disposable&&roll<80)p.ammunitionDrops.add(id);p.playerEquipmentN[slot]=count-1;if(count==1)p.playerEquipment[slot]=-1;p.getItems().setEquipment(p.playerEquipment[slot],p.playerEquipmentN[slot],slot,false);}
 public static void ground(Player p,Entity target){for(Integer id:p.ammunitionDrops)Server.itemHandler.createGroundItem(p,id,target.getX(),target.getY(),target.getHeight(),1,p.getIndex());p.ammunitionDrops.clear();}
 private static int count(Player p){int id=WeaponAliases.canonical(p.playerEquipment[3]);return id==11235||id>=12765&&id<=12768||p.usingSpecial&&(id==861||id==12788||id==22804)?2:1;}
 public static boolean enough(Player p){if(p.attacking.getCombatType()!=CombatType.RANGE)return true;int id=p.playerEquipment[3];if(p.getCombatItems().usingCrystalBow()||id>=11748&&id<=11758||id==12926||id==24106||id==22550)return true;int slot=p.usingOtherRangeWeapons?3:13;if(p.playerEquipmentN[slot]<count(p)){p.sendMessage("Municao insuficiente para este ataque.");return false;}return true;}
 public static void afterAttack(Player p,Entity target,io.xeros.content.combat.specials.Special special){int id=p.playerEquipment[3];if(p.getCombatItems().usingCrystalBow()||id>=11748&&id<=11758){p.crystalBowArrowCount++;return;}if(id==12926||id==24106||id==22550)return;int canonical=WeaponAliases.canonical(id),shots=canonical==11235||canonical>=12765&&canonical<=12768||special instanceof io.xeros.content.combat.specials.impl.MagicShortBow||special instanceof io.xeros.content.combat.specials.impl.DragonKnife?2:1;int slot=p.usingOtherRangeWeapons?3:13;for(int i=0;i<shots;i++)consume(p,slot);ground(p,target);}
 public static Boolean configureAlias(Player p){int raw=p.playerEquipment[3],id=WeaponAliases.canonical(raw);if(id==raw||WeaponData.forItemId(raw)!=WeaponData.BOW)return null;p.usingBow=true;p.usingOtherRangeWeapons=false;boolean crystal=p.getCombatItems().usingCrystalBow()||(id>=4212&&id<=4223)||(raw>=11748&&raw<=11758);if(crystal)return true;if(id==4734){p.usingCross=true;return p.playerEquipment[13]==4740&&p.playerEquipmentN[13]>0;}p.usingArrows=p.playerEquipmentN[13]>0&&Arrow.getArrow(p.playerEquipment[13]).isPresent();if(!p.usingArrows||!Bow.canUseArrow(p)){p.sendMessage("Equipe flechas compativeis com este arco.");return false;}return true;}
}
